const fs = require('fs');
const mqtt = require("mqtt");
const modbusClient = require("jsmodbus");
const net = require("net");
const { cleanData, buildDataCapture } = require("./Controller/prueba_test");
require("dotenv").config(); // Cargar variables del .env

// Opciones de conexión para MQTT
const options_WebSocket_Raspberry = {
  connectTimeout: 5000,
  clientId: 'camposol',
  keepalive: 60,
  clean: true,
};

const MQTT_URL = 'ws://38.253.154.122:8083/mqtt';
// const MQTT_URL = 'ws://192.168.18.18:8083/mqtt'
const client_MQTT = mqtt.connect(MQTT_URL, options_WebSocket_Raspberry);

client_MQTT.on("connect", () => {
  console.log("Cliente MQTT conectado.");
  client_MQTT.subscribe("consulte/topic", (err) => {
    if (err) console.error("Error al suscribirse a 'consulte/topic':", err);
    else console.log("Suscripción a 'consulte/topic' exitosa.");
  });
  client_MQTT.subscribe("consulte/write", (err) => {
    if (err) console.error("Error al suscribirse a 'consulte/write':", err);
    else console.log("Suscripción a 'consulte/write' exitosa.");
  });
});

// --- Procesamiento de la estructura de variables ---
// Lee y procesa el archivo de variables
const fileBuffer = fs.readFileSync('./variables.json');
const processedData = cleanData(fileBuffer); // { variables, DataSource }
const dataCapture = buildDataCapture(processedData.variables); 

// Configuración del PLC (ahora usando el rango basado en mw)
const plcConfigArray = [
  {
    plcName: "PLC_n1",
    host: "192.168.18.111",
    // host: '192.168.0.37',
    port: 502,
    dataCapture // Array con la estructura anidada de cada bloque
  }
  // Puedes agregar más PLCs con su propia configuración si lo deseas.
];

const MAX_DECIMAL = 3276.7;
const MIN_DECIMAL = -3276.8;

// --- Función para obtener datos del PLC usando Modbus ---
const obtenerDatosPLC = async () => {
  let DataArray = [];
  for (const plcConfig of plcConfigArray) {
    const { plcName, host, port, dataCapture } = plcConfig;
    const socket = new net.Socket();
    const client = new modbusClient.client.TCP(socket);
    try {
      await new Promise((resolve, reject) => {
        socket.connect({ host, port }, resolve);
      });

      // Procesamos cada bloque de la dataCapture
      for (const blockItem of dataCapture) {
        const blockName = Object.keys(blockItem)[0]; // Ej: "TK_NH3"
        const blockDef = blockItem[blockName];
        // Determinar el mínimo a partir de _topologicalAddress (ej. "%MW0" → 0)
        const blockMin = parseInt(blockDef._topologicalAddress.replace('%MW', ''), 10);
        // Recorremos todos los grupos y campos para determinar el máximo "mw" usado en el bloque
        let blockMax = blockMin;
        Object.keys(blockDef).forEach(key => {
          if (key === "_topologicalAddress") return;
          const group = blockDef[key]; // Por ejemplo, { GENERAL: { ... }, TPD: { ... } } o incluso una hoja
          Object.keys(group).forEach(groupKey => {
            const possibleLeaf = group[groupKey];
            if (
              typeof possibleLeaf === 'object' &&
              possibleLeaf !== null &&
              possibleLeaf.hasOwnProperty('type') &&
              possibleLeaf.hasOwnProperty('mw')
            ) {
              // Es una hoja, se procesa directamente
              const mwVal = parseInt(possibleLeaf.mw.replace('%MW', ''), 10);
              if (mwVal > blockMax) blockMax = mwVal;
            } else {
              // Es un objeto con más niveles, iteramos sus campos
              Object.keys(possibleLeaf).forEach(field => {
                const fieldDef = possibleLeaf[field];
                if (!fieldDef || typeof fieldDef.mw !== 'string') {
                  console.error(`El campo ${blockName}.${groupKey}.${field} no tiene propiedad "mw" definida.`);
                  return;
                }
                const mwVal = parseInt(fieldDef.mw.replace('%MW', ''), 10);
                if (mwVal > blockMax) blockMax = mwVal;
              });
            }
          });
        });

        // Se calcula el rango; se considera que de 0 a 124 son 125 registros, pero queremos 124 como máximo
        const range = blockMax - blockMin + 1;
        let registers = [];

        // Si el rango es menor o igual a 124, se lee en una sola petición
        if (range <= 124) {
          const resp = await client.readHoldingRegisters(blockMin, range);
          registers = resp.response._body.valuesAsArray;
        } else {
          // Si es mayor a 124, se realiza la lectura en partes (chunks de 124 registros)
          let tempRegs = [];
          for (let start = blockMin; start <= blockMax; start += 124) {
            const count = Math.min(124, blockMax - start + 1);
            const resp = await client.readHoldingRegisters(start, count);
            tempRegs = tempRegs.concat(resp.response._body.valuesAsArray);
          }
          registers = tempRegs;
        }

        // Recorremos nuevamente cada grupo y campo para asignar el valor leído
        Object.keys(blockDef).forEach(key => {
          if (key === "_topologicalAddress") return;
          const group = blockDef[key]; // Ej: { GENERAL: { CMD: {...}, EST: {...} }, ... }
          Object.keys(group).forEach(groupKey => {
            const possibleLeaf = group[groupKey];
            if (
              typeof possibleLeaf === 'object' &&
              possibleLeaf !== null &&
              possibleLeaf.hasOwnProperty('type') &&
              possibleLeaf.hasOwnProperty('mw')
            ) {
              // Se trata de una hoja directamente, no iteramos sus claves
              const fieldDef = possibleLeaf;
              if (!fieldDef || typeof fieldDef.mw !== 'string') {
                console.error(`El campo ${blockName}.${groupKey} no tiene propiedad "mw" definida.`);
                return;
              }
              const mwValue = parseInt(fieldDef.mw.replace('%MW', ''), 10);
              const offset = mwValue - blockMin;
              let value = registers[offset];
              if (value > 32767) value = value - 65536;
              let decimalValue = value * 0.1;
              if (decimalValue > MAX_DECIMAL || decimalValue < MIN_DECIMAL) {
                decimalValue = 0;
              }
              DataArray.push({
                plc: plcName,
                tag: fieldDef.tag, // Ej: "DESP1_DESH1.Seleccion"
                value: decimalValue,
                index: mwValue
              });
            } else {
              // Es una estructura anidada con campos dentro
              const fieldsObj = possibleLeaf;
              Object.keys(fieldsObj).forEach(field => {
                const fieldDef = fieldsObj[field];
                if (!fieldDef || typeof fieldDef.mw !== 'string') {
                  console.error(`El campo ${blockName}.${groupKey}.${field} no tiene propiedad "mw" definida.`);
                  return;
                }
                const mwValue = parseInt(fieldDef.mw.replace('%MW', ''), 10);
                const offset = mwValue - blockMin;
                let value = registers[offset];
                if (value > 32767) value = value - 65536;
                let decimalValue = value * 0.1;
                if (decimalValue > MAX_DECIMAL || decimalValue < MIN_DECIMAL) {
                  decimalValue = 0;
                }
                DataArray.push({
                  plc: plcName,
                  tag: fieldDef.tag, // Ej: "DESP1_DESH1.Hora", "DESP1_DESH1.Minuto", etc.
                  value: decimalValue,
                  index: mwValue
                });
              });
            }
          });
        });
      }
    } catch (error) {
      console.error(`Error en la conexión o lectura de ${plcName}:`, error);
    } finally {
      socket.destroy();
    }
  }
  client_MQTT.publish("topic_plc_data", JSON.stringify(DataArray));
};

// Función para escribir un valor decimal en el PLC
const escribirValorPLC = async (plcName, index, newValue, _id, oldValue, ambientId, tag) => {
  const plcConfig = plcConfigArray.find((plc) => plc.plcName === plcName);

  if (!plcConfig) {
    console.error(`PLC "${plcName}" no encontrado en la configuración.`);
    return;
  }

  const { host, port, startReg, endReg } = plcConfig;
  const socket = new net.Socket();
  const cliente = new modbusClient.client.TCP(socket);

  try {
    await new Promise((resolve, reject) => {
      socket.connect({ host, port }, resolve);
      socket.on("error", reject);
    });

    // Verificar el rango: si el valor ingresado excede los límites, se asigna 0
    if (newValue > MAX_DECIMAL || newValue < MIN_DECIMAL) {
      newValue = 0;
    }

    // Convertir el valor decimal a entero escalado (multiplicando por 100 para mantener dos decimales)
    const scaledValue = Math.round(newValue * 10);

    // Convertir a complemento a dos si el valor es negativo
    const registerValue = scaledValue < 0 ? (scaledValue & 0xFFFF) : scaledValue;

    // Escribir un solo registro en el PLC    
    await cliente.writeSingleRegister(index, registerValue);
    console.log(`Escrito en ${plcName} - Registro ${index}: ${registerValue}`);

    // Publicamos la confirmación de escritura (comentado)
    client_MQTT.publish("topic/registerCalibration/data", JSON.stringify({
      plc: plcName,
      index: index,
      value: newValue,
      status: "success",
      _id: _id,
      oldValue: oldValue,
      ambientId: ambientId,
      tag: tag
    }));
  } catch (error) {
    console.error(`Error al escribir en ${plcName}:`, error);
    // client_MQTT.publish("topic_plc_write_confirm", JSON.stringify({
    //   plc: plcName,
    //   index: index,
    //   value: newValue,
    //   status: "error",
    //   message: error.message
    // }));
  } finally {
    socket.destroy();
  }
};

// setInterval( async () => {
//   await obtenerDatosPLC();
// }, 1000);

// Cuando recibimos un mensaje en 'consulte/topic', ejecutamos la función para obtener datos del PLC
client_MQTT.on("message", async (topic, message) => {
  if (topic === "consulte/topic") {
    // console.log("Mensaje recibido en 'consulte/topic':", message.toString());
    await obtenerDatosPLC();
  }
  if (topic === "consulte/write") {
    try {
      const { plc, index, value, _id, oldValue, ambientId, tag } = JSON.parse(message.toString());
      await escribirValorPLC(plc, index, value, _id, oldValue, ambientId, tag);
    } catch (error) {
      console.error("Error al procesar el mensaje de escritura:", error);
    }
  }
});
